CREATE TABLE "news"."news_links" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "news_id" uuid NOT NULL, "order" integer NOT NULL DEFAULT 0, "kind" text NOT NULL, "cdtn_id" text, "label" text, "url" text, "intro" text, PRIMARY KEY ("id"), FOREIGN KEY ("news_id") REFERENCES "news"."news"("id") ON UPDATE cascade ON DELETE cascade, FOREIGN KEY ("cdtn_id") REFERENCES "public"."documents"("cdtn_id") ON UPDATE cascade ON DELETE cascade, CONSTRAINT "news_links_kind_check" CHECK (("kind" = 'cdtn' AND "cdtn_id" IS NOT NULL AND "label" IS NULL AND "url" IS NULL) OR ("kind" = 'external' AND "cdtn_id" IS NULL AND "label" IS NOT NULL AND "url" IS NOT NULL)));
COMMENT ON TABLE "news"."news_links" IS E'Contenus liés des actualités : contenus CDTN et liens externes';
